// VitePress build-time data loader for benchmark pages.
//
// The canonical source is `benchmarks/results.json` at the repo root,
// regenerated by `mise run bench` (which times ktx-daemon, ktx, and the
// system-installed kotlin/main-kts via hyperfine). The loader inlines
// the JSON into the bundle so the chart on /performance always matches
// the committed results.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// theme/ -> .vitepress/ -> docs/ -> repo root
const JSON_PATH = path.resolve(__dirname, "../../../benchmarks/results.json");

export interface BenchRow {
  key: string;
  label: string;
  values: Record<string, number | null>;
}

export interface BenchData {
  updated: string;
  unit: string;
  tools: string[];
  versions: Record<string, string>;
  rows: BenchRow[];
}

declare const data: BenchData;
export { data };

export default {
  watch: ["../../../benchmarks/results.json"],
  load(): BenchData {
    const raw = fs.readFileSync(JSON_PATH, "utf8");
    return JSON.parse(raw) as BenchData;
  },
};
